package com.sphere.core.clhep.geometry;

/**
 * CLHEP's HepGeom::Vector3D&lt;float&gt; (Geometry/Vector3D.h, Vector3D.cc): a displacement, which a
 * transformation turns by its rotation only. Generated by gen_geometry.py.
 */
public class Vector3DF extends BasicVector3DF {

    public Vector3DF() {
        super();
    }

    public Vector3DF(float x1, float y1, float z1) {
        super(x1, y1, z1);
    }

    /** From the first three of an array. */
    public Vector3DF(float[] a) {
        super(a[0], a[1], a[2]);
    }

    public Vector3DF(BasicVector3DF v) {
        super(v);
    }

    /** This vector turned by m's rotation. */
    public Vector3DF transform(Transform3D m) {
        final double vx = x();
        final double vy = y();
        final double vz = z();
        set((float) (m.xx() * vx + m.xy() * vy + m.xz() * vz),
            (float) (m.yx() * vx + m.yy() * vy + m.yz() * vz),
            (float) (m.zx() * vx + m.zy() * vy + m.zz() * vz));
        return this;
    }
}
